import{_ as a,o as i,c as s,a2 as t}from"./chunks/framework.DYPTBNgj.js";const g=JSON.parse('{"title":"Install","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started/installation.md","filePath":"getting-started/installation.md","lastUpdated":null}'),n={name:"getting-started/installation.md"};function r(l,e,o,p,d,c){return i(),s("div",null,[...e[0]||(e[0]=[t(`<h1 id="install" tabindex="-1">Install <a class="header-anchor" href="#install" aria-label="Permalink to &quot;Install&quot;">​</a></h1><h2 id="supported-platforms" tabindex="-1">Supported platforms <a class="header-anchor" href="#supported-platforms" aria-label="Permalink to &quot;Supported platforms&quot;">​</a></h2><p>The currently supported target is CachyOS with OpenZFS. The Arch User Repository packages may also work on compatible Arch Linux systems, but those systems are not currently supported.</p><h2 id="choose-a-package" tabindex="-1">Choose a package <a class="header-anchor" href="#choose-a-package" aria-label="Permalink to &quot;Choose a package&quot;">​</a></h2><div class="vp-code-group vp-adaptive-theme"><div class="tabs"><input type="radio" name="group-4SE-3" id="tab-xWd_Zzy" checked><label data-title="Arch Linux / derivatives" for="tab-xWd_Zzy">Arch Linux / derivatives</label></div><div class="blocks"><div class="language-text vp-adaptive-theme active"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>boomerangz      Build from the release source archive</span></span>
<span class="line"><span>boomerangz-bin  Install a prebuilt static binary</span></span></code></pre></div></div></div><p>The packages conflict and install the same executable, systemd unit, configuration, restricted SSH login-shell wrapper, manual pages, and shell completions. The source package builds with CGO disabled and Arch&#39;s PIE hardening. The binary package supports <code>x86_64</code> and <code>aarch64</code>.</p><p>Install one package with your preferred AUR workflow. Always inspect an AUR build recipe before running it.</p><div class="vp-code-group vp-adaptive-theme"><div class="tabs"><input type="radio" name="group-ZBDaJ" id="tab-i9sf6_k" checked><label data-title="Arch Linux / derivatives" for="tab-i9sf6_k">Arch Linux / derivatives</label></div><div class="blocks"><div class="language-sh vp-adaptive-theme active"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Example with an installed AUR helper:</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">paru</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -S</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> boomerangz</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Or choose the prebuilt release:</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">paru</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -S</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> boomerangz-bin</span></span></code></pre></div></div></div><p>Alternatively, download the generated <code>boomerangz-PKGBUILD</code> or <code>boomerangz-bin-PKGBUILD</code> from the matching GitHub release, place it in an empty directory as <code>PKGBUILD</code>, inspect it, and build as your normal user:</p><div class="vp-code-group vp-adaptive-theme"><div class="tabs"><input type="radio" name="group-cde29" id="tab-D8QES5m" checked><label data-title="Arch Linux / derivatives" for="tab-D8QES5m">Arch Linux / derivatives</label></div><div class="blocks"><div class="language-sh vp-adaptive-theme active"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">makepkg</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --syncdeps</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --install</span></span></code></pre></div></div></div><p>Release downloads are covered by SHA-256 checksums in both the package recipe and the release&#39;s <code>SHA256SUMS</code> file.</p><h2 id="prepare-the-service" tabindex="-1">Prepare the service <a class="header-anchor" href="#prepare-the-service" aria-label="Permalink to &quot;Prepare the service&quot;">​</a></h2><p>Before starting it:</p><ol><li>configure the required <a href="/guide/security#zfs-delegation">ZFS permissions</a>;</li><li>review <code>/etc/boomerangz/config.toml</code>;</li><li>install any <a href="/guide/remotes">remote credentials</a> with restrictive permissions;</li><li>validate the merged configuration.</li></ol><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">boomerangz</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check</span></span></code></pre></div><p>Then continue with <a href="./">Getting started</a>.</p><h2 id="upgrade-or-remove" tabindex="-1">Upgrade or remove <a class="header-anchor" href="#upgrade-or-remove" aria-label="Permalink to &quot;Upgrade or remove&quot;">​</a></h2><p>Upgrade through the same package channel you installed. Preserve the configured <code>identity_dir</code> (by default <code>/var/lib/boomerangz/identity</code>) when upgrading or restoring the same installation; never clone that identity directory to another active host.</p><p>Removing the package does not destroy datasets, snapshots, or replicated data. Use the preview-first <a href="/operations/recovery#explicit-clean">clean procedure</a> before removal only when you intentionally want to retire Boomerangz metadata.</p>`,19)])])}const u=a(n,[["render",r]]);export{g as __pageData,u as default};
